<script lang="ts">import { dishes, places, evidence } from '$lib/data'; import { progress, toggleProgress } from '$lib/progress'; $: remaining = dishes.filter(d => !$progress.tasted.includes(d.id)); $: candidates = places.map(p => ({ place:p, covers: evidence.filter(e => e.placeId === p.id && e.evidenceStatus !== 'unverified' && remaining.some(d => d.id === e.foodId)) })).filter(x => x.covers.length).sort((a,b) => b.covers.length-a.covers.length);</script>
<section class="pageintro"><p class="eyebrow">YOUR TASTING CHECKLIST</p><h1>What haven't you tried?</h1><p>Mark dishes as tasted. Suggested stops below cover the most remaining dishes with published evidence; this is a coverage count, not a restaurant ranking.</p></section>
<p class="muted">{$progress.tasted.length} of {dishes.length} dishes tasted</p><div class="checklist">{#each dishes as dish}<label class="foodcheck"><input type="checkbox" checked={$progress.tasted.includes(dish.id)} onchange={() => toggleProgress('tasted',dish.id)}/><span><a href="/foods/{dish.id}">{dish.italianName}</a><small>{dish.englishDescription}</small></span></label>{/each}</div>
<h2>Stops covering foods still on your list</h2><div class="cards">{#each candidates.slice(0,12) as candidate}<article class="card"><span class="tag">{candidate.place.city}</span><h3>{candidate.place.name}</h3><p class="muted">{candidate.covers.length} remaining dish{candidate.covers.length === 1 ? '' : 'es'} with sourced evidence</p><div class="chips">{#each candidate.covers as e}<a class="chip" href="/foods/{e.foodId}">{e.menuName}</a>{/each}</div></article>{/each}</div><p class="legend">Counts include restaurant-owned and third-party menu reports; check source quality on each dish page.</p>
